class InventoryReservationStateMachine {
  constructor(initialStock) {
    this.stock = initialStock;
    this.reservations = new Map();
    this.validTransitions = {
      PENDING: ['HELD', 'REJECTED'],
      HELD: ['COMMITTED', 'EXPIRED', 'RELEASED'],
      COMMITTED: [],
      EXPIRED: [],
      RELEASED: [],
      REJECTED: []
    };
  }

  createReservation(reservationId, sku, quantity) {
    if (quantity <= 0) throw new Error('Quantity must be positive');
    if (this.stock < quantity) {
      this.reservations.set(reservationId, { sku, quantity, state: 'REJECTED', updatedAt: Date.now() });
      return { success: false, reason: 'INSUFFICIENT_STOCK', remainingStock: this.stock };
    }

    this.stock -= quantity;
    this.reservations.set(reservationId, { sku, quantity, state: 'HELD', updatedAt: Date.now() });
    return { success: true, reservationId, state: 'HELD', remainingStock: this.stock };
  }

  transition(reservationId, targetState) {
    const res = this.reservations.get(reservationId);
    if (!res) throw new Error(`Reservation ${reservationId} not found`);

    const allowed = this.validTransitions[res.state] || [];
    if (!allowed.includes(targetState)) {
      throw new Error(`Illegal state transition from ${res.state} to ${targetState}`);
    }

    if ((targetState === 'EXPIRED' || targetState === 'RELEASED') && res.state === 'HELD') {
      this.stock += res.quantity; // Restore inventory to pool
    }

    res.state = targetState;
    res.updatedAt = Date.now();
    return { reservationId, state: targetState, remainingStock: this.stock };
  }
}

const sm = new InventoryReservationStateMachine(10);
const r1 = sm.createReservation('res_001', 'SKU_SHIRT', 3);
const r2 = sm.createReservation('res_002', 'SKU_SHIRT', 5);
const r3 = sm.createReservation('res_003', 'SKU_SHIRT', 4); // Exceeds remaining 2

