function executeLuaReservation(redisStore, sku, requestedQty, reservationId, ttlSec, nowMs = Date.now()) {
  // Emulate atomic Redis Lua script execution
  const stockKey = `{inventory:${sku}}:stock`;
  const holdsKey = `{inventory:${sku}}:holds`;
  const expiryKey = `{inventory:${sku}}:expiry_zset`;

  // 1. Read current stock atomically
  const currentStock = redisStore[stockKey] ?? 0;

  // 2. Over-allocation check
  if (currentStock < requestedQty) {
    return {
      success: false,
      code: 'ERR_INSUFFICIENT_STOCK',
      available: currentStock,
      requested: requestedQty
    };
  }

  // 3. Atomic Debit and Record
  redisStore[stockKey] = currentStock - requestedQty;
  if (!redisStore[holdsKey]) redisStore[holdsKey] = {};
  redisStore[holdsKey][reservationId] = requestedQty;

  if (!redisStore[expiryKey]) redisStore[expiryKey] = [];
  const expiresAtMs = nowMs + (ttlSec * 1000);
  redisStore[expiryKey].push({ reservationId, expiresAtMs, quantity: requestedQty });
  // Maintain sorted order by expiresAtMs
  redisStore[expiryKey].sort((a, b) => a.expiresAtMs - b.expiresAtMs);

  return {
    success: true,
    code: 'RESERVATION_GRANTED',
    reservationId,
    allocated: requestedQty,
    remainingStock: redisStore[stockKey],
    expiresAtMs
  };
}

const mockRedis = {
  '{inventory:IPHONE_16}:stock': 5
};

const reqA = executeLuaReservation(mockRedis, 'IPHONE_16', 2, 'res_A', 300, 1000);
