class DistributedFencingGate {
  constructor() {
    this.fencingCounter = 100;
    this.currentLockHolder = null;
    this.highestObservedToken = 0;
    this.storage = {};
  }

  acquireLock(clientId, resource) {
    this.fencingCounter += 1;
    const token = this.fencingCounter;
    this.currentLockHolder = { clientId, resource, token };
    return { acquired: true, token, clientId };
  }

  releaseLock(clientId, token) {
    if (this.currentLockHolder && this.currentLockHolder.token === token) {
      this.currentLockHolder = null;
      return true;
    }
    return false;
  }

  // Downstream storage gate: strictly enforces monotonically increasing tokens
  commitStorageWrite(resource, data, fencingToken) {
    if (fencingToken <= this.highestObservedToken) {
      return {
        success: false,
        error: 'STALE_FENCING_TOKEN',
        message: `Write rejected: token ${fencingToken} <= highest observed ${this.highestObservedToken}`
      };
    }

    this.highestObservedToken = fencingToken;
    this.storage[resource] = { ...data, committedWithToken: fencingToken, committedAt: Date.now() };
    return {
      success: true,
      committedWithToken: fencingToken,
      resource
    };
  }
}

const gate = new DistributedFencingGate();

// Client 1 acquires lock
const lock1 = gate.acquireLock('worker_pod_1', 'order_999');
console.log('Client 1 Lock Token:', lock1.token);

// Client 1 suffers GC pause... Meanwhile Client 2 acquires lock
const lock2 = gate.acquireLock('worker_pod_2', 'order_999');
console.log('Client 2 Lock Token:', lock2.token);

// Client 2 writes to storage FIRST
const write2 = gate.commitStorageWrite('order_999', { status: 'CONFIRMED', user: 'bob' }, lock2.token);
console.log('Client 2 Write Success:', write2.success, 'Token:', write2.committedWithToken);

// Client 1 wakes up from GC pause and attempts to write with stale token
const write1 = gate.commitStorageWrite('order_999', { status: 'CONFIRMED', user: 'alice' }, lock1.token);
console.log('Client 1 Stale Write Success:', write1.success, 'Error:', write1.error);

function runReservationExpirationReaper(redisStore, sku, nowMs) {
  const stockKey = `{inventory:${sku}}:stock`;
  const holdsKey = `{inventory:${sku}}:holds`;
  const expiryKey = `{inventory:${sku}}:expiry_zset`;

  const expiredCandidates = (redisStore[expiryKey] || []).filter(e => e.expiresAtMs <= nowMs);
  const reaped = [];
  const skipped = [];

  for (const item of expiredCandidates) {
    const { reservationId, quantity } = item;
    const currentHold = redisStore[holdsKey]?.[reservationId];

    if (currentHold !== undefined) {
      // 1. Atomically restore inventory to stock pool
      redisStore[stockKey] = (redisStore[stockKey] || 0) + quantity;
      // 2. Remove hold
      delete redisStore[holdsKey][reservationId];
      // 3. Remove from expiry set
      redisStore[expiryKey] = redisStore[expiryKey].filter(e => e.reservationId !== reservationId);
      reaped.push({ reservationId, restoredQuantity: quantity });
    } else {
      // Already committed or released previously, just clean from expiry set
      redisStore[expiryKey] = redisStore[expiryKey].filter(e => e.reservationId !== reservationId);
      skipped.push(reservationId);
    }
  }

  return {
    sku,
    reapedCount: reaped.length,
    reapedReservations: reaped,
    skippedCount: skipped.length,
    updatedStock: redisStore[stockKey]
  };
}

